css:
@page { size: A4 landscape; margin: 0; }
html, body { margin: 0; padding: 0; }
.print-format { padding: 0 !important; margin: 0 !important; max-width: none !important; width: 297mm; }
.qc-page {
	width: 297mm;
	height: 210mm;
	box-sizing: border-box;
	padding: 11mm;
	background: #fbf8f2;
	color: #2a211c;
	font-family: var(--q-font-body, Arial, sans-serif);
	-webkit-print-color-adjust: exact;
	print-color-adjust: exact;
}
.qc-frame {
	height: 100%;
	box-sizing: border-box;
	border: 1.2pt solid var(--qc-accent);
	outline: 0.5pt solid var(--qc-accent);
	outline-offset: -3mm;
	padding: 12mm 22mm 9mm;
	display: flex;
	flex-direction: column;
	align-items: center;
	text-align: center;
}
.qc-head { display: flex; flex-direction: column; align-items: center; gap: 5mm; }
.qc-logo { max-height: 14mm; max-width: 60mm; object-fit: contain; }
.qc-name-logo {
	font-family: var(--q-font-heading, Arial, sans-serif);
	font-stretch: 62%;
	font-weight: 900;
	text-transform: uppercase;
	font-size: 22pt;
	line-height: 1;
	color: var(--qc-accent);
}
.qc-label {
	font-family: var(--q-font-body, Arial, sans-serif);
	font-weight: 700;
	font-size: 9pt;
	letter-spacing: 0.16em;
	text-transform: uppercase;
	color: var(--qc-accent);
}
.qc-muted { color: #6b5d52; }
.qc-body { flex: 1; display: flex; flex-direction: column; justify-content: center; align-items: center; gap: 3mm; }
.qc-quote {
	font-family: var(--q-font-accent, Georgia, serif);
	font-style: italic;
	font-size: 15pt;
	color: #6b5d52;
}
.qc-member {
	font-family: var(--q-font-heading, Arial, sans-serif);
	font-stretch: 62%;
	font-weight: 900;
	text-transform: uppercase;
	font-size: 62pt;
	line-height: 0.96;
	color: var(--qc-accent);
	margin: 1mm 0 2mm;
	max-width: 230mm;
	text-wrap: balance;
}
.qc-course {
	font-family: var(--q-font-accent, Georgia, serif);
	font-style: italic;
	font-size: 26pt;
	line-height: 1.15;
	color: #2a211c;
	margin-bottom: 2mm;
	max-width: 220mm;
	text-wrap: balance;
}
.qc-sign { display: flex; gap: 22mm; justify-content: center; width: 100%; margin-bottom: 7mm; }
.qc-sig { min-width: 62mm; text-align: left; }
.qc-sig-line {
	font-family: var(--q-font-accent, Georgia, serif);
	font-style: italic;
	font-size: 14pt;
	white-space: nowrap;
	border-bottom: 0.6pt solid #6b5d52;
	padding-bottom: 1.5mm;
	margin-bottom: 1.8mm;
}
.qc-foot { font-size: 7pt; }

html:
{#- Qernel Learn: the Søndagsbilag certificate (lms/qernel_design.py,
    certificate_design). A4 landscape, rendered by Chrome. Fonts and logo come
    inline, so nothing is fetched while the PDF is made. -#}
{%- set cd = certificate_design(doc) -%}
<style>
@page { size: A4 landscape; margin: 0; }
{% if cd %}{{ cd.css }}{% endif %}
</style>
{%- if cd %}
<div class="qc-page" style="--qc-block: {{ cd.block }}; --qc-accent: {{ cd.accent }};">
	<div class="qc-frame">
		<div class="qc-head">
			{%- if cd.logo %}
			<img class="qc-logo" src="{{ cd.logo }}" alt="{{ cd.name | e }}">
			{%- else %}
			<div class="qc-name-logo">{{ cd.name | e }}</div>
			{%- endif %}
			<div class="qc-label">{{ _("Certificate") }}</div>
		</div>
		<div class="qc-body">
			<div class="qc-quote">{{ _("This confirms that") }}</div>
			<div class="qc-member">{{ cd.member_name | e }}</div>
			<div class="qc-quote">{{ _("has completed the course") }}</div>
			<div class="qc-course">{{ cd.course_title | e }}</div>
			{%- if cd.lessons %}
			<div class="qc-label qc-muted">{{ _("{0} lessons").format(cd.lessons) }}</div>
			{%- endif %}
		</div>
		<div class="qc-sign">
			{%- if cd.instructor %}
			<div class="qc-sig">
				<div class="qc-sig-line">{{ cd.instructor | e }}</div>
				<div class="qc-label qc-muted">{{ _("Course leader") }}</div>
			</div>
			{%- endif %}
			<div class="qc-sig">
				<div class="qc-sig-line">{{ cd.issue_date }}</div>
				<div class="qc-label qc-muted">{{ _("Date") }}</div>
			</div>
		</div>
		<div class="qc-foot qc-label qc-muted">{{ cd.name | e }} · Powered by Qernel</div>
	</div>
</div>
{%- else %}
{%- set member = frappe.db.get_value("User", doc.member, "full_name") %}
<div style="padding: 40mm; text-align: center; font-family: Georgia, serif;">
	<p>{{ _("This confirms that") }}</p>
	<h1>{{ member | e }}</h1>
	<p>{{ _("has completed the course") }}</p>
	<h2>{{ frappe.db.get_value("LMS Course", doc.course, "title") | e }}</h2>
	<p>{{ frappe.utils.format_date(doc.issue_date, "medium") }}</p>
</div>
{%- endif %}
